const SOLO_LECTURA = false
// EL RECONCILIADOR DE DESPACHOS HUÉRFANOS · la lógica pura · CC#1 · 2026-09-30 · GO de Emilio (evaluación 30-sep §6/§10).
// Un RELOJ aparte que mira el SÍNTOMA («despacho aceptado, sin recibo, sin vuelta») y no la causa, para que las dos causas medidas
// (saldo agotado · tope de la vuelta de Vercel a los 800 s) y cualquier causa futura se VEAN en vez de perderse.
// REGLA 8 de la evaluación: todo arreglo tiene que hacer DISTINGUIBLE «terminó y no pudo entregar» de «nunca arrancó».
// Lógica PURA (sin red, sin `this`, sin `URL`, sin `require` fuera de este archivo): se prueba a costo cero y se pega en el nodo del reloj.
//
// Entradas por despacho (`agent_dispatches`): status accepted|running|completed|error · created_at · workflow_execution_id · agent_name.
// Contexto: `invocacion` = la fila de `agent_invocations` (misma ejecución y agente, posterior al despacho; se escribe AL TERMINAR el trabajo)
//           `intentos`   = filas de `agent_callback_attempts` cuya dirección trae esa ejecución (`/webhook-waiting/<ejecución>`).

var PARAMETROS = {
  // un despacho aceptado que no llega a «running» en 3 min no arrancó (el marcador running se escribe a los segundos)
  ACEPTADO_MAX_S: 180,
  // un agente puede tardar mucho (medido: 32 min); pasada 1 h sin ninguna señal de vida, se da por muerto
  CORRIENDO_MAX_S: 3600,
  // el callback llega a los segundos de terminar el trabajo: 3 min de gracia antes de dar el resultado por «no entregado»
  GRACIA_ENTREGA_S: 180,
}

var CLASES = {
  ok: { severidad: 'ok', que: 'despacho cerrado' },
  en_curso: { severidad: 'ok', que: 'trabajando dentro de lo esperado' },
  entregado_ledger_abierto: { severidad: 'info', que: 'la vuelta SÍ se entregó pero el registro del despacho quedó abierto' },
  error_entregado: { severidad: 'info', que: 'falló y el error SÍ le llegó al que esperaba' },
  error_callback_409: { severidad: 'info', que: 'falló; el que llamó no espera por callback (lo sondea): sus intentos dan 409' },
  termino_y_no_entrego: { severidad: 'alta', que: 'TERMINÓ el trabajo y NADIE lo entregó · el resultado existe · el que esperaba no se enteró' },
  nunca_arranco: { severidad: 'alta', que: 'se ACEPTÓ el trabajo y NUNCA arrancó' },
  sin_senales_de_vida: { severidad: 'alta', que: 'lleva más de 1 h «corriendo» sin ninguna señal de vida · probablemente murió' },
  error_sin_entrega: { severidad: 'alta', que: 'FALLÓ y el error NO le llegó al que esperaba (sin intentos de vuelta o todos fallaron) · su espera puede estar colgada' },
}

function segundos(desde, hasta) {
  var a = new Date(desde).getTime()
  var b = typeof hasta === 'number' ? hasta : new Date(hasta).getTime()
  return Math.round((b - a) / 1000)
}

/** ¿La dirección de una fila de intentos es la de esta ejecución? (sin `URL`: solo texto) */
function intentoDeLaEjecucion(url, ejecucion) {
  if (!url || !ejecucion) return false
  return String(url).indexOf('/webhook-waiting/' + String(ejecucion) + '?') !== -1 || String(url).slice(-('/webhook-waiting/' + String(ejecucion)).length) === '/webhook-waiting/' + String(ejecucion)
}

/** Empareja la invocación de un despacho: misma ejecución + mismo agente + creada DESPUÉS del despacho (menos 5 s de tolerancia). */
function invocacionDe(despacho, invocaciones) {
  var t0 = new Date(despacho.created_at).getTime() - 5000
  var mejor = null
  for (var i = 0; i < (invocaciones || []).length; i++) {
    var v = invocaciones[i]
    if (String(v.workflow_execution_id) !== String(despacho.workflow_execution_id)) continue
    if (v.agent_name !== despacho.agent_name) continue
    if (new Date(v.created_at).getTime() < t0) continue
    if (!mejor || new Date(v.created_at) < new Date(mejor.created_at)) mejor = v
  }
  return mejor
}

/**
 * Clasifica UN despacho. Devuelve { clasificacion, severidad, que, evidencia }.
 * `ahora` en milisegundos. NO modifica nada.
 */
function clasificarDespacho(despacho, invocacion, intentos, ahora, params) {
  var P = params || PARAMETROS
  var edad = segundos(despacho.created_at, ahora)
  var ok = (intentos || []).filter(function (x) { return x.status === 'ok' })
  var fallidos = (intentos || []).filter(function (x) { return x.status !== 'ok' })
  var todos409 = (intentos || []).length > 0 && fallidos.length === (intentos || []).length && fallidos.every(function (x) { return Number(x.http_status_code) === 409 })
  var evidencia = {
    dispatch_key: despacho.dispatch_key || null,
    agente: despacho.agent_name,
    ejecucion: String(despacho.workflow_execution_id),
    estado_del_registro: despacho.status,
    edad_s: edad,
    intentos_de_vuelta: (intentos || []).length,
    intentos_ok: ok.length,
    ultimo_intento: (intentos || []).length ? (intentos[intentos.length - 1].status + (intentos[intentos.length - 1].http_status_code ? '/' + intentos[intentos.length - 1].http_status_code : '')) : null,
    invocacion: invocacion ? { id: invocacion.id || null, creada: invocacion.created_at, duracion_ms: invocacion.duration_ms, costo_usd: invocacion.cost_usd, estado: invocacion.status } : null,
  }
  var salir = function (clase, extra) {
    return { clasificacion: clase, severidad: CLASES[clase].severidad, que: CLASES[clase].que, evidencia: extra ? Object.assign(evidencia, extra) : evidencia }
  }

  if (despacho.status === 'completed') return salir('ok')
  // 01-nov · ya lo cerró el ciclo de vida de los incidentes, con su motivo: deja de ser un hallazgo
  if (despacho.status === 'sin_cierre') return salir('ok')

  if (despacho.status === 'error') {
    if (ok.length) return salir('error_entregado')
    if (todos409) return salir('error_callback_409')
    return salir('error_sin_entrega')
  }

  // accepted | running → sin cerrar
  if (ok.length) {
    // entregada la vuelta pero el registro sigue abierto: solo se declara cuando ya pasó la gracia
    return edad > P.GRACIA_ENTREGA_S ? salir('entregado_ledger_abierto') : salir('en_curso')
  }
  if (invocacion) {
    var desdeQueTermino = segundos(invocacion.created_at, ahora)
    if (desdeQueTermino >= P.GRACIA_ENTREGA_S) return salir('termino_y_no_entrego', { desde_que_termino_s: desdeQueTermino })
    return salir('en_curso')
  }
  if (despacho.status === 'accepted') {
    return edad > P.ACEPTADO_MAX_S ? salir('nunca_arranco') : salir('en_curso')
  }
  // running sin invocación (la fila aparece AL TERMINAR): solo se da por muerto pasado el tope de vida esperado
  return edad > P.CORRIENDO_MAX_S ? salir('sin_senales_de_vida') : salir('en_curso')
}

/** Clasifica todos los despachos y devuelve solo lo que hay que registrar (severidad alta o info). */
function reconciliar(despachos, invocaciones, intentos, ahora, params) {
  var out = []
  for (var i = 0; i < (despachos || []).length; i++) {
    var d = despachos[i]
    var inv = invocacionDe(d, invocaciones)
    var ints = (intentos || []).filter(function (x) { return intentoDeLaEjecucion(x.callback_url, d.workflow_execution_id) })
    ints.sort(function (a, b) { return new Date(a.attempted_at || a.created_at).getTime() - new Date(b.attempted_at || b.created_at).getTime() })
    var c = clasificarDespacho(d, inv, ints, ahora, params)
    out.push({ despacho: d, resultado: c })
  }
  return out
}


// «Reconciliar» · el cuerpo del nodo del reloj · CC#1 · 2026-09-30. La lógica pura `clasificar.js` va ANTEPUESTA por el constructor.
// Lee (solo lectura) los despachos de las últimas 72 h + sus invocaciones + sus intentos de vuelta, los clasifica, y registra en
// `agent_dispatch_reconciliations` lo que hay que ver. NO toca `agent_dispatches`, ni el corredor, ni Vercel, ni ningún flujo.
// `SOLO_LECTURA` (lo inyecta el constructor: true SOLO en la copia de prueba) clasifica y devuelve, sin escribir ni avisar.
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const VENTANA_H = 72
const ahora = Date.now()
const desde = new Date(ahora - VENTANA_H * 3600 * 1000).toISOString()
const leer = async (ruta) => this.helpers.httpRequest({ url: SB + '/rest/v1/' + ruta, method: 'GET', json: true, timeout: 30000, headers: auth })
const escribir = async (metodo, ruta, cuerpo, extra) => this.helpers.httpRequest({
  url: SB + '/rest/v1/' + ruta, method: metodo, json: true, body: cuerpo, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 30000,
  headers: { ...auth, 'Content-Type': 'application/json', ...(extra || {}) },
})

const despachos = await leer('agent_dispatches?created_at=gte.' + desde + '&select=id,dispatch_key,workflow_execution_id,agent_name,client_id,status,created_at,running_at,completed_at&order=created_at&limit=1000')
const ejecs = [...new Set(despachos.map((d) => String(d.workflow_execution_id)).filter((x) => x && x !== 'null'))]
const invocaciones = ejecs.length
  ? await leer('agent_invocations?workflow_execution_id=in.(' + ejecs.join(',') + ')&created_at=gte.' + new Date(ahora - (VENTANA_H + 1) * 3600 * 1000).toISOString() + '&select=id,workflow_execution_id,agent_name,created_at,duration_ms,cost_usd,status&limit=2000')
  : []
const intentos = await leer('agent_callback_attempts?created_at=gte.' + desde + '&select=callback_url,attempt_number,status,http_status_code,attempted_at,created_at&limit=5000')
const clave = (d) => d.dispatch_key || 'id:' + d.id
const resultados = reconciliar(despachos, invocaciones, intentos, ahora)
const aRegistrar = resultados.filter((r) => r.resultado.severidad === 'alta' || r.resultado.severidad === 'info')
const resumen = { despachos: despachos.length, ok: resultados.filter((r) => r.resultado.severidad === 'ok').length, info: aRegistrar.filter((r) => r.resultado.severidad === 'info').length, alta: aRegistrar.filter((r) => r.resultado.severidad === 'alta').length }
const detalle = resultados.map((r) => ({ ejecucion: String(r.despacho.workflow_execution_id), agente: r.despacho.agent_name, estado: r.despacho.status, clasificacion: r.resultado.clasificacion, severidad: r.resultado.severidad }))

if (SOLO_LECTURA) return [{ json: { modo: 'solo_lectura', resumen, detalle, avisos: [], escribio: false } }]

// lo ya registrado y sin resolver (para no avisar dos veces y para marcar lo resuelto)
const existentes = await leer('agent_dispatch_reconciliations?resuelta_el=is.null&select=dispatch_key,avisado_el,clasificacion')
const yaAvisado = {}
existentes.forEach((e) => { yaAvisado[e.dispatch_key] = !!e.avisado_el })

const ts = new Date(ahora).toISOString()
if (aRegistrar.length) {
  const filas = aRegistrar.map((r) => ({
    dispatch_key: clave(r.despacho), agente: r.despacho.agent_name, ejecucion: String(r.despacho.workflow_execution_id), cliente: r.despacho.client_id || null,
    clasificacion: r.resultado.clasificacion, severidad: r.resultado.severidad, que: r.resultado.que, evidencia: r.resultado.evidencia, ultima_vez: ts, resuelta_el: null,
  }))
  // merge-duplicates: en una fila que ya existe solo se actualizan las columnas del cuerpo (primera_vez y avisado_el NO se pisan)
  const w = await escribir('POST', 'agent_dispatch_reconciliations?on_conflict=dispatch_key', filas, { Prefer: 'resolution=merge-duplicates,return=minimal' })
  if (w.statusCode >= 300) throw new Error('RECONCILIADOR_SIN_ANOTAR · la tabla respondió HTTP ' + w.statusCode + ' · ' + JSON.stringify(w.body).slice(0, 240))
}
// lo que ya no es un problema (el despacho se cerró / llegó la vuelta) se marca resuelto
const vigentes = {}
aRegistrar.forEach((r) => { vigentes[clave(r.despacho)] = true })
const resueltos = existentes.map((e) => e.dispatch_key).filter((k) => !vigentes[k])
if (resueltos.length) {
  const p = await escribir('PATCH', 'agent_dispatch_reconciliations?dispatch_key=in.(' + resueltos.map((k) => '"' + k + '"').join(',') + ')', { resuelta_el: ts }, { Prefer: 'return=minimal' })
  if (p.statusCode >= 300) throw new Error('RECONCILIADOR_SIN_RESOLVER · HTTP ' + p.statusCode)
}
const avisos = aRegistrar
  .filter((r) => r.resultado.severidad === 'alta' && !yaAvisado[clave(r.despacho)])
  .map((r) => ({
    dispatch_key: clave(r.despacho), clasificacion: r.resultado.clasificacion, que: r.resultado.que, agente: r.despacho.agent_name,
    ejecucion: String(r.despacho.workflow_execution_id), edad_s: r.resultado.evidencia.edad_s, invocacion: r.resultado.evidencia.invocacion,
    intentos: r.resultado.evidencia.intentos_de_vuelta, ultimo_intento: r.resultado.evidencia.ultimo_intento,
  }))
return [{ json: { modo: 'real', resumen, avisos, resueltos: resueltos.length, escribio: true } }]

// «Armar el aviso» · CC#1 · 2026-09-30. Un solo mensaje por pasada con los hallazgos NUEVOS de severidad alta.
const a = $input.first().json
const base = ($env.N8N_BASE_URL || 'https://n8n-production-72be.up.railway.app').split('/').slice(0, 3).join('/')
const QUE_HACER = {
  termino_y_no_entrego: 'el resultado EXISTE (agent_invocations / punto de control): recuperarlo y abrir la ejecución; su espera venció o vence',
  nunca_arranco: 'el trabajo NO corrió (no costó): reintentar el despacho',
  sin_senales_de_vida: 'revisar el corredor de Railway (¿se reinició?) y reintentar si no hay resultado',
  error_sin_entrega: 'el flujo puede seguir esperando: abrir la ejecución y cancelarla',
}
const lineas = a.avisos.slice(0, 8).map((x) => {
  const inv = x.invocacion ? ' · invocación `' + String(x.invocacion.id || '?').slice(0, 8) + '` (' + Math.round((x.invocacion.duracion_ms || 0) / 1000) + ' s · US$ ' + x.invocacion.costo_usd + ')' : ''
  return '• *' + x.clasificacion + '* — ' + x.que + '\n   agente `' + x.agente + '` · ejecución <' + base + '/workflow/_/executions/' + x.ejecucion + '|' + x.ejecucion + '> · edad ' + Math.round(x.edad_s / 60) + ' min · intentos de vuelta ' + x.intentos + (x.ultimo_intento ? ' (' + x.ultimo_intento + ')' : '') + inv + '\n   → ' + (QUE_HACER[x.clasificacion] || 'revisar')
})
const extra = a.avisos.length > 8 ? '\n… y ' + (a.avisos.length - 8) + ' más (ver agent_dispatch_reconciliations)' : ''
return [{ json: { ...a, titulo: 'Despachos huérfanos: ' + a.avisos.length + ' nuevo(s)', texto: lineas.join('\n') + extra, claves: a.avisos.map((x) => x.dispatch_key) } }]

// «Marcar avisados» · CC#1 · 2026-09-30. Lección E81 de los avisos: la marca «avisado» se pone SOLO cuando Slack confirma ok:true.
// Si Slack no confirmó, NO se marca (el próximo reloj vuelve a intentar) y la corrida falla RUIDOSA para que se vea.
const previo = $('Armar el aviso').first().json
const r = $input.first().json || {}
const slack = r.body ? r.body : r
if (!slack || slack.ok !== true) {
  throw new Error('RECONCILIADOR_AVISO_NO_LLEGO · Slack no confirmó ok:true (' + String((slack && slack.error) || 'sin respuesta') + ') · los hallazgos NO se marcan avisados · se reintenta en el próximo reloj')
}
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const w = await this.helpers.httpRequest({
  url: SB + '/rest/v1/agent_dispatch_reconciliations?dispatch_key=in.(' + previo.claves.map((k) => '"' + k + '"').join(',') + ')', method: 'PATCH', json: true,
  body: { avisado_el: new Date().toISOString() }, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 30000, headers: { ...auth, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
})
if (w.statusCode >= 300) throw new Error('RECONCILIADOR_SIN_MARCAR · HTTP ' + w.statusCode)
return [{ json: { avisados: previo.claves.length } }]
